                            ' \\hline\n'
                            ' & 1\n'
                            ' \\end{array}\n'
                            '$$\n'
                            '\n'
                            '$$\n'
                            '60=2 \\times 2 \\times 3 \\times 5\n'
                            '$$\n'
                            '\n'
                            '$$\n'
                            '\\begin{array}{r | r}\n'
